/** A target kind's own noun with its first letter made a capital, as the review pane draws it. */
function capitalisedNoun(kind: TargetKind): string {
  const noun = TARGET_SPECS_BY_KIND[kind].noun
  return noun.charAt(0).toUpperCase() + noun.slice(1)
}

