  "dev.queries.unusedQuestion": "Which records is nothing else built on? A record is on this list when nothing else says it uses it.",
  "dev.queries.unusedReason": "A result that nothing consumes is a finding that never reached the work it should have changed. Check whether its users have linked to it.",
  "dev.queries.unusedAct": "Open the record. If a task, module or pipeline uses it, add a “{consumes}” link from that record to this result. It then leaves this list. If nothing uses it, leave it here.",
  "dev.queries.unusedScope": "Only {kinds} records are considered — a {task} or an {obligation} is not a result, so nothing consuming it means nothing. Deleted records are not counted. Links of every other type are ignored: a record can be discussed, measured and contradicted by ten others and still be here.",
  "dev.queries.nothingYet": "Nothing here yet.",
  "dev.queries.allUsed": "Everything something else could build on, something else does build on — as far as the links say.",
  "dev.queries.missingUnknown": "needs a record that is not in the database at all — not even its title was kept",
  "dev.queries.missingDeleted": "needs “{title}”, which has been deleted",
  "dev.queries.missingQuestion": "Which records consume something that is not there? A row appears when a {consumes} link points at a record that has been deleted, or at an id with no record behind it. One row is one such LINK, not one record: a record consuming two missing things is two rows here.",
  "dev.queries.missingReason": "This is the broken-link case seen from the side of the work that is stuck. Deleted records are retained so their users can find the missing result here.",
  "dev.queries.missingAct": "Restore the missing record from the consumer's page, where the link is drawn as Broken with a Restore button beside it. If it was deleted on purpose, unlink it there instead: the row is telling you the consumer's assumptions changed.",
  "dev.queries.missingScope": "Only {consumes} links are checked — that is the one whole-graph link query the server has. A broken link of any other type is just as real and does not appear here: {others} all show on the record's own page instead.",
