  "sheet.labelHintAndErrorAreWiredToTheControl": "Label, hint and error are wired to the control by id, so a screen reader hears all three. The hint is behind the question mark rather than under the box: a reader who knows the field should not have to read it again. A field that may be left empty says so beside its label, because that is the one fact a fold must not hide.",
