  "sheet.exampleLanternArchiveReportMd": "/example/lantern-archive/report.md",
  "sheet.absenceAtThreeWeights": "Absence, at three weights",
  "sheet.oneTestDecidesTheWeightDoesTheReaderHave": "One test decides the weight: does the reader have to do something about this absence? Ordinary emptiness is a dimmed dash and never a sentence. “Nobody looked” and “there are none” have to stay tellable apart, so one is enclosed in a dashed edge — a gap somebody can close — and the other is enclosed in nothing, because it is an answer. Only an absence that is itself the finding gets a sentence.",
