  "sheet.emptyErrorLoading": "Empty, error, loading",
  "sheet.fourDifferentEmptyMessagesNeverOneNoResultsEmpty": "Four different empty messages, never one “no results”. Empty is an absence whose caller has not said which of the three it is, so it is drawn quietly — the sentence stays and the box is gone. Loading holds the final geometry so nothing jumps when the data lands.",
