  "sheet.records": "records",
  "sheet.incompleteIsNotBroken": "Incomplete is not broken",
  "sheet.bothAreOnThisPageAtOnceSoThey": "Both are on this page at once so they can be compared. The alarm above says content is present and lying; the block below says content is absent and that is allowed. Different colour, different structure, different weight, different word — squint at it, or switch data-theme to mono, and the two still do not converge.",
  "sheet.partsIsPresentButIsNotAListPart": "`parts` is present but is not a list. Part 2 has no name.",
  "sheet.dataContextIsNotFilledInSoThisModule": "data.context is not filled in, so this module is incomplete. Say why the module exists and what would go wrong without it. The record is kept either way; fill it in when you know it. Example: \"A scanner for the Lantern archive. The desk camera cannot read labels on the lower shelf.\"",
  "sheet.dataPartsIsNotFilledInSoThisModule": "data.parts is not filled in, so this module is incomplete. The progress checklist, grouped into named parts. Send [] when there is nothing on the checklist yet — an empty checklist is an answer, and it counts as complete. The record is kept either way — fill it in when you know it. Example: [{\"id\":\"mount\",\"name\":\"Scanner stand\",\"items\":[]}]",
