  "g6a.sessions.doesNotListAlsoaffectsSoWhatElseWould": "does not list `alsoAffects`, so what else would die with it is unknown",
  "g6a.sessions.hasAnEntryInAlsoaffectsThatIsNot": "has an entry in `alsoAffects` that is not a description",
  "g6a.sessions.isPresentButIsNotAListSo": "`{value1}` is present but is not a list, so nothing in it could be shown.",
  "g6a.sessions.isNotASentenceSoItCouldNot": "`{value1}[{value2}]` is not a sentence, so it could not be shown.",
  "g6a.sessions.theUnclaimedBlockIsNotAnObjectSo": "The `unclaimed` block is {value1}, not an object, so nothing could be said about what is running that no session claims.",
  "g6a.sessions.theUnclaimedSweepCarriesNoSummarySoThe": "The `unclaimed` sweep carries no `summary`, so the server's own sentence about it is missing. The rows below are still shown.",
  "g6a.sessions.theUnclaimedSweepHasNoResourcesListSo": "The `unclaimed` sweep has no `resources` list, so nothing can be shown as running unclaimed — which is not the same as nothing running unclaimed.",
  "g6a.sessions.unclaimedResourcesIsPresentButIsNotA": "`unclaimed.resources` is present but is not a list.",
  "g6a.sessions.hasTypeWhichIsNotOneOfIt": "{value1} has type {value2}, which is not one of {value3}. It is not shown, because the panel would not know what it is holding.",
  "g6a.sessions.hasNoKeySoThereIsNothingTo": "{value1} has no `key`, so there is nothing to name it by. It was: {value2}",
  "g6a.sessions.carriesNoDetailSoWhatItIsRunning": "{value1} (\"{value2} {value3}\") carries no `detail`, so what it is running is unknown.",
  "g6a.sessions.carriesNoNoteSoTheServerSaidNothing": "{value1} (\"{value2} {value3}\") carries no `note`, so the server said nothing about what to do with it by hand.",
  "g6a.sessions.unclaimedSkippedIsPresentButIsNotA": "`unclaimed.skipped` is present but is not a list, so what the sweep left out could not be shown.",
