  "g6a.sessions.theBrowserRefusedClipboardAccessSelectTheCommand": "The browser refused clipboard access. Select the command above and copy it by hand.",
  "g6a.sessions.ageUnknown": "age unknown",
  "g6a.sessions.moleOfficeNeverDeletesLockFilesAndThis": "Mole Office never deletes lock files, and this is one. A lock is often the only evidence that a job is still running, and removing it lets a second copy start on the same data — a worse outcome than a stale lock. Look at it, then remove it yourself.",
  "g6a.sessions.theServerDidNotSayExactlyWhatKilling": "The server did not say exactly what killing this would act on, so there is no button. Mole Office will not offer a release it cannot describe. Stop it by hand, then check it is actually free.",
  "g6a.sessions.nothingWasKilledTheMachineChangedBetweenThis": "Nothing was killed. The machine changed between this row being read and the button being pressed, and the server refused rather than act on the old reading. It said: {value1} This is not retried — read the machine again and decide against what is there now.",
  "g6a.sessions.nothingWasKilledTheSentenceThisPageShowed": "Nothing was killed. The sentence this page showed you is not the sentence the server would act on now, so what is on this screen is a stale reading of the machine — which is how the wrong thing gets killed. It said: {value1} Read the machine again.",
  "g6a.sessions.released": "Released:",
