  "g6a.sessions.theSessionIsGoneAndSomethingItStarted": "The session is gone and something it started is not. What it left, and what stopping that would take, is on the machine surface below.",
  "g6a.sessions.idle": "idle",
  "g6a.sessions.aliveAndEachHasSaidNothingSinceThe": "Alive, and each has said nothing since the time on its row. `idle` is the word this product stores and it is kept: the reason beside it is the one that was recorded, and Mole Office never reads a question out of a transcript to decide that a run is waiting on you.",
  "g6a.sessions.running": "running",
  "g6a.sessions.workingRightNowNothingInThisGroupNeeds": "Working right now. Nothing in this group needs you; it is here so that \"is anything moving\" is answerable.",
