  "g6a.sessions.nobodyHasSaidWhatHappenedToTheseIt": "No state was ever written for these: a gap in the record, not an answer. Each row still shows the Unknown chip the sweep observed, beside the mark No state written.",
  "g6a.sessions.carryingAStateWordNobodyHasClassified": "carrying an unclassified state word",
  "g6a.sessions.eachRecordHoldsAWordThisProductHas": "Each record holds a word this product has never said the meaning of, so Mole Office cannot tell whether the work stopped short. That is a question for a person, and the word is printed on the row exactly as it was written.",
  "g6a.sessions.moleOfficeCannotPlace": "Mole Office cannot place",
  "g6a.sessions.theSessionsApiReportsTheseAsUnknownAnd": "The sessions list reports these as unknown and the session records were not read, so a judgement of unknown cannot be told from no state written. Both are in this group.",
