  "g6a.sessions.howARunIsPlacedAndWhatEach": "how a run is placed, and what each state word means",
  "g6a.sessions.stateGroupsOnThisPage": "state groups on this page",
  "g6a.sessions.moleOfficePlacesARunUsingTwoThings": "Mole Office places a run using two things it recorded itself: a typed link between the session record and a pipeline or module, and the change log, which says which records each run wrote to. A run that wrote to a record linked to a pipeline or module is placed through that record, and the record is named on the row. A title is never read: it is typed text, and a rule that reads titles can be fooled by one.",
  "g6a.sessions.aWorkingFolderCanContainSeveralModulesSo": "A working folder can contain several modules, so the folder does not decide where a run belongs.",
  "g6a.sessions.aRunThatReachesMoreThanOnePipeline": "A run that reaches more than one pipeline or module is filed under the one with the strongest evidence, and the others are named inside that row so the choice can be disagreed with.",
  "g6a.sessions.everyRowOpensOntoWhatMoleOfficeRecorded": "Every row opens onto what Mole Office recorded about that one run, and the number beside “what was recorded” is how many of these {value1} that row actually has:",
