  'lists.pipelines.inspect': 'This page reads the pipelines, their blocks, the links and the attention list (shape flow). Deleted records are omitted.',
  'lists.order.pipelines': "Needs you lists the steps on the attention list: first any step that records a person could be hurt, then by the score the server gave it. A blocked step is listed there only when it records that a person could be hurt, because no record says what a blocked step waits on. The pipelines are grouped by the step each one is standing on: its first failed step, else its first blocked step, else its first step under way, else its first step not started. In each group, first comes any pipeline holding a step that records a person could be hurt, then how many of its steps are on the attention list, then the best score the server gave one of them, then how many of its steps have failed. A blocked step counts towards none of the last three.",
