  "sourcePage.staleClaims.why": "This is what a rename does to a curated model. The module still reads as if it covers the code; the code has moved. Nothing fails, nobody is told, and the module quietly becomes a description of a repository that no longer exists.",
  "sourcePage.staleClaims.act": "Open the module and point the claim at the new path. It is the module that is out of date, not the scan — the scan is right about what exists — so nothing here can be edited to make a row go away.",
  "sourcePage.staleClaims.emptyLead": "Every claim resolves to something real.",
  "sourcePage.staleClaims.emptyBody": "Each path claimed by a module matched at least one file in this scan. That is a statement about this scan and nothing else: a rename made after it ran is not in this answer.",
  "sourcePage.unclaimed.why": "An unclaimed file is not a fault. It is the question “who would you ask about this?” with no answer — worth knowing before the person who wrote it is unavailable, and it is how a front end ends up invisible in a tracker built to make work visible.",
  "sourcePage.unclaimed.emptyLead": "Every file in the index is claimed by a module.",
  "sourcePage.unclaimed.emptyBody": "All {n} of them resolve from at least one module's claims.",
  "sourcePage.moduleClaims.noModules": "There are no module records in this workspace yet, so nothing claims any of the code below.",
