  "sourcePage.search.alreadyEmpty": "The search box is already empty.",
  "sourcePage.allFiles.emptyLead": "The scan found no files at all.",
  "sourcePage.allFiles.emptyBody": "That is a statement about the scan, not about the repository: an empty index almost always means it was pointed at the wrong root, which this one reports as {root}.",
  "sourcePage.error.nothingInstead": "Nothing is listed instead. An empty page here would read as “no unclaimed code and no stale claims”, which is the opposite of what just happened.",
