  "chk.read.handedOn": { one: "A checker handed on {n} path for judgment.", other: "A checker handed on {n} paths for judgment." },
  "chk.notItsOwnTree": "This check did not read a worktree of its own. Criterion C30 asks for a detached worktree at the run tip, never the worker’s own tree, because two processes writing one working tree is not evidence about either.",
  "chk.closeThisRun": "Close this run",
  "chk.noInspectorConfirm": "This project asked for no inspector, so no check will release this run. Confirming it closes it, and the record will say it was confirmed and not checked.",
  "chk.reportedNobodyAnybody": "This run reported to nobody, so anybody registered may confirm the report and close the run.",
  "chk.waitingForReport": "This run is waiting for {who} to confirm the report. Nothing removes its worktree until then.",
  "chk.whatYouAreSaying": "What you are saying when you confirm it",
  "chk.confirmPlaceholder": "Read the report and the pictures. The three criteria are met.",
  "chk.sayFirst": "Say what you are confirming first. A close with nothing behind it cannot be told from a mis-press a year later.",
  "chk.confirmAndClose": "Confirm the report and close the run",
  "chk.nothingOwed": "Nothing is still owed for this run.",
  "chk.checkFailed": "Check failed",
  "chk.checkNotStarted": "Check not started",
  "chk.askAgain": "Ask for the check again",
  "chk.askingAgain": "Asking for a check…",
  "chk.standing.closedUnchecked.word": "Closed unchecked",
  "chk.standing.closedUnchecked.sentence": "This run was closed unchecked, with the reason recorded. Nothing is still owed for it.",
  "chk.standing.working.word": "Still working",
  "chk.standing.working.sentence": "This run has not said its work is finished, so there is nothing to check yet.",
  "chk.standing.inspecting.word": "Being checked",
  "chk.standing.inspecting.sentence": "This run said its work is finished and the office is having it checked. It is still a live run: its worktree is kept and nothing about it is removed while this lasts. A subagent saying it is done does not end it.",
  "chk.standing.rebuttal.word": "Refused, under discussion",
  "chk.standing.rebuttal.sentence": "The check refused to release this run, and the refusal stands while it is talked out in the group that was opened for it. The run does not end here. It ends one of two ways: the worker fixes what is missing and says its work is finished again, which sends it back to be checked, or the group agrees nothing is wrong and somebody releases it.",
  "chk.standing.reporting.word": "Waiting for its report to be confirmed",
  "chk.standing.reporting.sentence": "The check released this run, and its report waits to be confirmed. While it waits, the run stays open and nothing removes its worktree.",
  "chk.standing.closed.word": "Closed",
  "chk.standing.closed.sentence": "The report was confirmed, so this run is over and what it was holding can be let go.",
  "chk.standing.superseded.word": "Superseded",
  "chk.standing.superseded.sentence": "A later run finished the work this run was for: it was on the same branch, or it was checked and merged and holds this run's commits. This run was closed as superseded by it. Its seal, its report, its refusals and any release are exactly as they were, and nothing is still owed for it. The later run is the one to read.",
  "chk.standingNoCheck.inspecting.word": "Waiting for the secretary",
  "chk.workerRound.word": "Awaiting the round",
  "chk.workerRound.sentence": "No check was asked for this worker run. Its work is checked in its supervisor's round. After that round merges, its supervisor, a secretary or the owner closes this run.",
  "chk.workerRound.waiting": "Waiting for the supervisor's round to be checked and merged. Then someone must close this run.",
  "chk.standingNoCheck.inspecting.sentence": "This run said its work is finished. This project asked for no inspector, so the office started no check and nothing has read this run against the office regulations. It is still a live run, and it waits for the secretary rather than for a check. The work is sealed as it always is; the seal blocks nobody.",
  "chk.standingNoCheck.closed.word": "Closed, not checked",
  "chk.standingNoCheck.closed.sentence": "This run was confirmed and is over. No check released it: this project asked for no inspector, so nothing read this work against the office regulations. What the confirmation proves is which work was accepted, where it named a seal, and who accepted it.",
