  'moduleSource.howRead': 'Imports and exports are found by matching patterns in the text, not by reading the code fully. TypeScript, JavaScript and Python files show both. CSS and HTML files show imports only, and a SQL migration shows neither. So a name inside a comment or a string can appear, and an unusual form can be missed. These lists help you find your way; nothing in Mole Office decides anything from them.',

